import re
import os

def clean_matrix_data(input_data, is_file=True):
    """
    행렬 데이터에서 'L' 접미사를 제거하고 정제하는 함수
    """
    print("[*] =============== Data Cleaning Start ===============")
    
    raw_content = ""
    if is_file:
        if not os.path.exists(input_data):
            print(f"[!] 에러: 파일을 찾을 수 없습니다 -> {input_data}")
            return
        print(f"[*] 입력 파일 읽는 중: {input_data}")
        with open(input_data, 'r', encoding='utf-8') as f:
            raw_content = f.read()
    else:
        print("[*] 입력 문자열 처리 중...")
        raw_content = input_data

    original_len = len(raw_content)
    print(f"[*] 원본 데이터 길이: {original_len}자")

    # 1. 숫자 뒤에 붙은 'L' 제거 (예: 123L -> 123, 0xabcL -> 0xabc)
    # 정규표현식 설명: (\d+|0x[0-9a-fA-F]+)는 숫자 또는 16진수를 캡처하고 뒤의 L만 매칭
    cleaned_content = re.sub(r'([0-9a-fA-Fx]+)L', r'\1', raw_content)
    
    # 2. 결과 분석 및 디버깅 정보 출력
    removed_count = (original_len - len(cleaned_content))
    print(f"[*] 제거된 'L' 문자 수: 약 {removed_count}개")
    
    # 3. 데이터 구조 검증 (간단히)
    row_count = cleaned_content.count('[') - 1 # 전체 리스트 제외
    print(f"[*] 감지된 행(Row) 개수: {row_count}")

    print("[*] ---------------------------------------------------")
    print("[*] 정제된 데이터 앞부분 샘플 (100자):")
    print(f"    {cleaned_content[:100]}...")
    print("[*] ---------------------------------------------------")

    # 4. 파일로 저장
    output_file = "cleaned_matrix.txt"
    with open(output_file, 'w', encoding='utf-8') as f:
        f.write(cleaned_content)
    
    print(f"[+] 정제 완료! 결과가 '{output_file}'에 저장되었습니다.")
    print("[+] 이 파일의 내용을 복사해서 Z3 스크립트의 matrix 변수에 넣으세요.")
    print("[*] =============== Data Cleaning End =================\n")

